import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a d-dimensional Euclidean space, consider {num_sets} closed convex sets K_1, ..., K_{num_sets}. A point p is called encapsulated if there exists a ball centered at p with sufficiently small radius such that every point in this ball except p is contained in at least one of the sets K_i. Let S be the set of all encapsulated points with respect to these {num_sets} convex sets. Over all possible choices of the sets, let f({dimension}, {num_sets}) = max |S| depend only on the parameters {dimension} and {num_sets}. Determine the exact value of f({dimension}, {num_sets}).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate (dimension, num_sets) so that the instance is nontrivial
# and the induced answer is reasonably large to discourage guessing.
# Use retries to meet constraints.
for _ in range(1000):
    d = rng.randint(2, 9)         # dimension in [2, 9]
    m = rng.randint(4, 10)        # number of sets in [4, 10]
    # Proposed closed-form answer: f(d, m) = m * floor(d/2) + 1 + (d mod 2)
    f_val = m * (d // 2) + 1 + (d % 2)
    # Enforce nontrivial size to make guessing hard
    if f_val >= 10:
        return {'dimension': d, 'num_sets': m}
# Fallback: if random failed (unlikely), choose a safe default
d, m = 8, 10
return {'dimension': d, 'num_sets': m}

    def verifier(assign):
# Validate keys and compute the closed-form answer
# Returns (True, answer) if valid; otherwise (False, None).
try:
    d = assign['dimension']
    m = assign['num_sets']
except Exception:
    # Missing keys
    return (False, None)
# Type checks
if not isinstance(d, int) or not isinstance(m, int):
    return (False, None)
# Domain checks
if d < 2 or m < 4:
    return (False, None)
# Compute the asserted maximum
# Derived recurrence and construction yield:
# f(d, m) = m * floor(d/2) + 1 + (d mod 2)
answer = m * (d // 2) + 1 + (d % 2)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

